}

// NewLimiterWithClock is like NewLimiter but accepts an injectable Clock.
func NewLimiterWithClock(capacity int, rate float64, clock Clock) (*Limiter, error) {
	if capacity <= 0 || rate <= 0 {
		return nil, ErrInvalidConfig
	}
	if clock == nil {
		return nil, errors.New("ratelimit: nil clock")
	}
	return &Limiter{
		clock:    clock,
		capacity: capacity,
		rate:     rate,
		tokens:   float64(capacity),
		last:     clock.Now(),
	}, nil
}

// AllowN reports whether n tokens may be consumed at time now.
// If yes, the tokens are deducted and it returns true; otherwise false.
func (l *Limiter) AllowN(n int) bool {
	return l.allowAt(l.clock.Now(), n)
}

// Allow reports whether one token may be consumed now.
func (l *Limiter) Allow() bool { return l.AllowN(1) }

func (l *Limiter) allowAt(now time.Time, n int) bool {
	l.mu.Lock()
	defer l.mu.Unlock()

	// Refill based on elapsed time since last update.
	elapsed := now.Sub(l.last).Seconds()
	if elapsed > 0 {
		l.tokens = min(float64(l.capacity), l.tokens+elapsed*l.rate)
		l.last = now
	}
	if n < 0 || float64(n) > l.tokens {
		return false
	}
	l.tokens -= float64(n)
	return true
}

func min(a, b float64) float64 {
	if a < b {
		return a
	}
