// Limiter is a concurrency-safe token-bucket rate limiter.
// A Limiter must be created with New; the zero value is not usable.
type Limiter struct {
	mu        sync.Mutex
	tokens    float64
	max       float64
	rate      float64 // tokens per second
	lastRefill time.Time
	clock     Clock
}

// ErrInvalidConfig is returned by New for invalid parameters.
var ErrInvalidConfig = errors.New("ratelimit: capacity and refill rate must be positive")

// New creates a Limiter with the given burst capacity (tokens), refill
// rate (tokens per second), and clock. The bucket starts full.
func New(capacity int, refillPerSec float64, clock Clock) (*Limiter, error) {
	if capacity <= 0 || refillPerSec <= 0 {
		return nil, ErrInvalidConfig
	}
	if clock == nil {
		clock = realClock{}
	}
	return &Limiter{
		tokens:    float64(capacity),
		max:       float64(capacity),
		rate:      refillPerSec,
		lastRefill: clock.Now(),
		clock:     clock,
	}, nil
}

type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// AllowN reports whether n tokens are available at time now, consuming
// them if so. n must be positive; a non-positive n returns false.
func (l *Limiter) AllowN(now time.Time, n int) bool {
	if n <= 0 {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()

	elapsed := now.Sub(l.lastRefill).Seconds()
	if elapsed > 0 {
		l.tokens = min(l.max, l.tokens+elapsed*l.rate)
		l.lastRefill = now
	}
	if l.tokens < float64(n) {
		return false
	}
	l.tokens -= float64(n)
	return true
}

// Allow reports whether a single token is available.
func (l *Limiter) Allow() bool {
	return l.AllowN(l.clock.Now(), 1)
}

func min(a, b float64) float64 {
	if a < b {
		return a
	}
	return b
}
