func TestAllowN(t *testing.T) {
	base := time.Unix(0, 0)
	tests := []struct {
		name     string
		capacity int
		rate     float64
		steps    []struct {
			advance time.Duration
			n       int
			want    bool
		}
	}{
		{
			name: "burst up to capacity then denied",
			capacity: 3, rate: 1,
			steps: []struct {
				advance time.Duration
				n       int
				want    bool
			}{
				{0, 1, true},
				{0, 1, true},
				{0, 1, true},
				{0, 1, false},
			},
		},
		{
