			capacity: 2, rate: 1,
			steps: []struct {
				advance time.Duration
				n       int
				want    bool
			}{
				{0, 2, true},          // drain
				{0, 1, false},         // empty
				{time.Second, 1, true},  // 1 token refilled
				{0, 1, false},
				{time.Second, 2, true},  // capped at capacity
			},
		},
		{
			name: "partial refill insufficient",
			capacity: 1, rate: 2,
			steps: []struct {
				advance time.Duration
				n       int
				want    bool
			}{
				{0, 1, true},
				{time.Second / 2, 1, true}, // exactly 1 token
				{time.Second / 4, 1, false},
			},
		},
		{
			name: "non-positive n denied",
			capacity: 1, rate: 1,
			steps: []struct {
				advance time.Duration
				n       int
				want    bool
			}{
				{0, 0, false},
				{0, -1, false},
				{0, 1, true},
			},
		},
	}

	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
