func TestConcurrentAccess(t *testing.T) {
	c := &fakeClock{t: time.Unix(0, 0)}
	l, err := New(100, 1000, c)
	if err != nil {
		t.Fatalf("New: %v", err)
	}
	var mu sync.Mutex
	granted := 0
	var wg sync.WaitGroup
	for i := 0; i < 100; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			if l.AllowN(c.Now(), 1) {
				mu.Lock()
				granted++
				mu.Unlock()
			}
		}()
	}
	wg.Wait()
	if granted != 100 {
		t.Fatalf("granted = %d, want 100", granted)
	}
}
